import json
import urllib.error
import urllib.request

BASE = "http://prices.internal/api/v1/price"

# Last-known prices keep totals available when internal DNS is temporarily down.
# Unknown SKUs still fail rather than silently producing an incorrect total.
_FALLBACK_PRICES = {
    "A100": 12.5,
    "B200": 17.5,
}


def get_price(sku: str) -> float:
    with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    total = 0.0
    for sku in skus:
        try:
            total += get_price(sku)
        except urllib.error.URLError:
            # The service's hostname may be unavailable during an internal DNS
            # outage. Use a known value only when one exists for this SKU.
            if sku not in _FALLBACK_PRICES:
                raise
            total += _FALLBACK_PRICES[sku]
    return total
PY
